SELECT
tc.*,
pt.name AS toilet_name,
ct.complaint_name AS complaint_type_name,
u.user_name AS handler_Name
FROM public_toilet_complaint tc
LEFT JOIN public_toilet pt ON tc.toilet_id = pt.toilet_id AND pt.deleted = 0
LEFT JOIN sys_complaint_type ct ON tc.complaint_type_id = ct.complaint_type_id AND ct.deleted = 0
LEFT JOIN sys_user u ON u.user_id = tc.handler_id AND u.deleted = 0
WHERE tc.deleted = 0



    AND tc.complaint_id = #{reqVO.complaintId}


    AND tc.toilet_id = #{reqVO.toiletId}


    AND tc.complaint_type_id = #{reqVO.complaintTypeId}


    AND tc.content LIKE CONCAT('%', #{reqVO.content}, '%')


    AND tc.complaint_name LIKE CONCAT('%', #{reqVO.complaintName}, '%')


    AND tc.phone LIKE CONCAT('%', #{reqVO.phone}, '%')




    AND tc.complaint_time BETWEEN #{reqVO.complaintTime[0]} AND #{reqVO.complaintTime[1]}




    AND tc.dispatch_status IN

        #{status}





    AND tc.handler_id = #{reqVO.handlerId}




    AND tc.is_timeout = #{reqVO.isTimeout}




    AND tc.handle_measure LIKE CONCAT('%', #{reqVO.handleMeasure}, '%')




    AND tc.handle_result LIKE CONCAT('%', #{reqVO.handleResult}, '%')




    AND tc.feedback_content LIKE CONCAT('%', #{reqVO.feedbackContent}, '%')




    AND pt.name LIKE CONCAT('%', #{reqVO.toiletName}, '%')


    AND ct.complaint_name LIKE CONCAT('%', #{reqVO.complaintTypeName}, '%')


    AND u.user_name LIKE CONCAT('%', #{reqVO.handlerName}, '%')




    AND tc.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}




    AND tc.update_time BETWEEN #{reqVO.updateTime[0]} AND #{reqVO.updateTime[1]}


ORDER BY tc.id DESC
LIMIT #{reqVO.offset}, #{reqVO.pageSize}

